rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function errf() { return resource.data.missing == 1; }
    function lazyLet() { let x = resource.data.missing; return true; }
    function usedLet() { let x = resource.data.missing; return x == 1 || true; }
    function nonBool() { return 1; }
    function ignores(a) { return true; }
    function uses(a) { return a == 1 || true; }
    match /c_missing_eq/{doc} {
      allow get: if resource.data.missing == 1;
    }
    match /c_missing_ne_null/{doc} {
      allow get: if resource.data.missing != null;
    }
    match /c_null_field_eq_null/{doc} {
      allow get: if resource.data.nul == null;
    }
    match /c_err_or_true/{doc} {
      allow get: if resource.data.missing == 1 || true;
    }
    match /c_true_or_err/{doc} {
      allow get: if true || resource.data.missing == 1;
    }
    match /c_err_or_false/{doc} {
      allow get: if resource.data.missing == 1 || false;
    }
    match /c_false_or_err/{doc} {
      allow get: if false || resource.data.missing == 1;
    }
    match /c_err_and_false/{doc} {
      allow get: if resource.data.missing == 1 && false;
    }
    match /c_false_and_err/{doc} {
      allow get: if false && resource.data.missing == 1;
    }
    match /c_err_and_true/{doc} {
      allow get: if resource.data.missing == 1 && true;
    }
    match /c_true_and_err/{doc} {
      allow get: if true && resource.data.missing == 1;
    }
    match /c_err_or_err/{doc} {
      allow get: if resource.data.missing == 1 || 1 / 0 == 0;
    }
    match /c_not_err/{doc} {
      allow get: if !(resource.data.missing == 1);
    }
    match /c_not_not_err/{doc} {
      allow get: if !!(resource.data.missing == 1);
    }
    match /c_paren_err_or_true_and/{doc} {
      allow get: if (resource.data.missing == 1 || true) && (true || resource.data.missing == 1);
    }
    match /c_err_and_false_or_true/{doc} {
      allow get: if (resource.data.missing == 1 && false) || true;
    }
    match /c_false_and_err_or_true/{doc} {
      allow get: if (false && resource.data.missing == 1) || true;
    }
    match /c_ternary_err_cond/{doc} {
      allow get: if (resource.data.missing == 1) ? true : true;
    }
    match /c_ternary_true_skips_err/{doc} {
      allow get: if true ? true : (resource.data.missing == 1);
    }
    match /c_ternary_false_skips_err/{doc} {
      allow get: if false ? (resource.data.missing == 1) : true;
    }
    match /c_ternary_takes_err/{doc} {
      allow get: if true ? (resource.data.missing == 1) : true;
    }
    match /c_err_eq_err/{doc} {
      allow get: if (resource.data.missing == 1) == (resource.data.missing == 1);
    }
    match /c_err_ne_true/{doc} {
      allow get: if (resource.data.missing == 1) != true;
    }
    match /c_err_eq_false/{doc} {
      allow get: if (resource.data.missing == 1) == false;
    }
    match /c_err_in_list/{doc} {
      allow get: if (resource.data.missing == 1) in [true, false];
    }
    match /c_in_missing_list/{doc} {
      allow get: if 1 in resource.data.missing;
    }
    match /c_err_list_literal/{doc} {
      allow get: if [resource.data.missing == 1].size() == 1;
    }
    match /c_err_map_literal_value/{doc} {
      allow get: if {'a': resource.data.missing == 1}.size() == 1;
    }
    match /c_fn_err/{doc} {
      allow get: if errf();
    }
    match /c_fn_ignores_err_arg/{doc} {
      allow get: if ignores(resource.data.missing);
    }
    match /c_fn_uses_err_arg_or_true/{doc} {
      allow get: if uses(resource.data.missing);
    }
    match /c_fn_ignores_div_zero_arg/{doc} {
      allow get: if ignores(1 / 0);
    }
    match /c_horses_or_true/{doc} {
      allow get: if 'horses' || true;
    }
    match /c_true_or_horses/{doc} {
      allow get: if true || 'horses';
    }
    match /c_horses_and_false/{doc} {
      allow get: if 'horses' && false;
    }
    match /c_fn_err_or_true/{doc} {
      allow get: if errf() || true;
    }
    match /c_let_unused_err/{doc} {
      allow get: if lazyLet();
    }
    match /c_missing_key_in/{doc} {
      allow get: if 'missing' in resource.data;
    }
    match /c_present_key_in/{doc} {
      allow get: if 'n' in resource.data;
    }
    match /c_missing_get_default/{doc} {
      allow get: if resource.data.get('missing', 7) == 7;
    }
    match /c_nested_get_default/{doc} {
      allow get: if resource.data.get(['m', 'x'], 0) == 1;
    }
    match /c_nested_get_missing_default/{doc} {
      allow get: if resource.data.get(['m', 'q'], 7) == 7;
    }
    match /c_nested_get_missing_parent/{doc} {
      allow get: if resource.data.get(['missing', 'q'], 7) == 7;
    }
    match /c_nested_get_through_scalar/{doc} {
      allow get: if resource.data.get(['n', 'q'], 7) == 7;
    }
    match /c_nested_missing_key/{doc} {
      allow get: if resource.data.m.q == 1;
    }
    match /c_null_member/{doc} {
      allow get: if resource.data.nul.x == 1;
    }
    match /c_scalar_member/{doc} {
      allow get: if resource.data.n.x == 1;
    }
    match /c_string_plus_int/{doc} {
      allow get: if resource.data.s + 1 == 'abc1';
    }
    match /c_string_lt_int/{doc} {
      allow get: if resource.data.s < 1;
    }
    match /c_int_eq_string/{doc} {
      allow get: if resource.data.n == 'a';
    }
    match /c_int_ne_string/{doc} {
      allow get: if resource.data.n != 'a';
    }
    match /c_int_eq_float/{doc} {
      allow get: if 1 == 1.0;
    }
    match /c_int_lt_float/{doc} {
      allow get: if 1 < 1.5;
    }
    match /c_null_eq_null/{doc} {
      allow get: if null == null;
    }
    match /c_null_lt_int/{doc} {
      allow get: if null < 1;
    }
    match /c_string_cmp/{doc} {
      allow get: if 'a' < 'b' && 'B' < 'a';
    }
    match /c_nonbool_int_or_true/{doc} {
      allow get: if 1 || true;
    }
    match /c_true_or_nonbool_int/{doc} {
      allow get: if true || 1;
    }
    match /c_nonbool_string_and_true/{doc} {
      allow get: if 'abc' && true;
    }
    match /c_false_and_nonbool/{doc} {
      allow get: if false && 1;
    }
  }
}

