    match /c_not_nonbool/{doc} {
      allow get: if !1;
    }
    match /c_nonbool_condition_fn/{doc} {
      allow get: if nonBool();
    }
    match /c_nonbool_condition_field/{doc} {
      allow get: if resource.data.n;
    }
    match /c_nonbool_condition_null/{doc} {
      allow get: if resource.data.nul;
    }
    match /c_ternary_nonbool_cond/{doc} {
      allow get: if 1 ? true : false;
    }
    match /c_div_zero/{doc} {
      allow get: if 1 / 0 == 0;
    }
    match /c_div_zero_or_true/{doc} {
      allow get: if 1 / 0 == 0 || true;
    }
    match /c_float_div_zero_inf/{doc} {
      allow get: if 1.0 / 0.0 > 100000000000000000000.0;
    }
    match /c_float_div_int_zero/{doc} {
      allow get: if 1.0 / 0 > 100000000000000000000.0;
    }
    match /c_neg_float_div_zero/{doc} {
      allow get: if -1.0 / 0.0 < -100000000000000000000.0;
    }
    match /c_zero_div_zero_nan/{doc} {
      allow get: if math.isNaN(0.0 / 0.0);
    }
    match /c_float_mod_zero/{doc} {
      allow get: if math.isNaN(1.5 % 0.0);
    }
    match /c_int_max_plus_one/{doc} {
      allow get: if 9223372036854775807 + 1 < 0;
    }
    match /c_int_min_minus_one/{doc} {
      allow get: if -9223372036854775807 - 2 > 0;
    }
    match /c_int_min_div_neg1/{doc} {
      allow get: if (-9223372036854775807 - 1) / -1 < 0;
    }
    match /c_int_min_mod_neg1/{doc} {
      allow get: if (-9223372036854775807 - 1) % -1 == 0;
    }
    match /c_int_of_huge_float/{doc} {
      allow get: if int(100000000000000000000.0) > 0;
    }
    match /c_int_of_inf/{doc} {
      allow get: if int(1.0 / 0.0) > 0;
    }
    match /c_int_of_nan/{doc} {
      allow get: if int(0.0 / 0.0) == 0;
    }
    match /c_int_div_trunc/{doc} {
      allow get: if 7 / 2 == 3 && -7 / 2 == -3;
    }
    match /c_int_mod_sign/{doc} {
      allow get: if -7 % 2 == -1 && 7 % -2 == 1;
    }
    match /c_float_div/{doc} {
      allow get: if 7.0 / 2 == 3.5 && 7 / 2.0 == 3.5;
    }
    match /c_unknown_request_field/{doc} {
      allow get: if request.foo == 1;
    }
  }
